const body = $input.first().json.body ?? $input.first().json;
return [{
  json: {
    ...body,
    t1_start: new Date().toISOString(),
  },
}];

const d = $input.first().json;
const itemsList = (d.items ?? []).map(i => `- ${i.qty}x ${i.name} (${i.line}, talle ${i.size})`).join('\n');

const message_text = `Nuevo lead recibido — Golden Harvest S.A.\n\n` +
  `Cliente: ${d.contact?.nombre ?? '(sin nombre)'}\n` +
  `Empresa: ${d.contact?.empresa ?? '-'}\n` +
  `Email: ${d.contact?.email ?? '-'}\n` +
  `Teléfono: ${d.contact?.telefono ?? '-'}\n\n` +
  `Productos solicitados:\n${itemsList}\n\n` +
  `Quote ID: ${d.quoteId}\n` +
  `[SIMULADO] Este mensaje representa la notificación que en producción se enviaría por WhatsApp Business API y SendGrid al equipo de ventas.`;

return [{ json: { ...d, message_text } }];

// El nodo Gmail reemplaza el JSON de entrada por la respuesta de la API de Gmail
// ({id, threadId, labelIds}), así que quoteId/t1_start/clientSubmittedAt no sobreviven
// si se leen de $input. Se leen del nodo anterior a Gmail en su lugar.
const d = $('Armar Mensaje (Simulado)').first().json;
const t1_end = new Date().toISOString();
const latency_ms_n8n_internal = new Date(t1_end).getTime() - new Date(d.t1_start).getTime();
return [{
  json: {
    quoteId: d.quoteId,
    sessionId: d.sessionId,
    clientSubmittedAt: d.clientSubmittedAt ?? null,
    t1_start: d.t1_start,
    t1_end,
    latency_ms_n8n_internal,
  },
}];
